#!/usr/bin/env python3
"""THE single source of truth for every training-pair file. Scans disk, records
count+hash+schema+git-status, merges a CURATED status, and FAILS on drift.

Jesse 2026-07-22: "Are we keeping track of all the training pairs being generated properly?"
Answer at build time was NO — version duplicates with no canonical marker, a QUARANTINED file
(ui_thinking_rows_v1, which all 5 lanes said DO NOT TRAIN) tracked but unmarked, and large pair
files (kr_substrate 3965, candidates 870) gitignored = not in version control.

This manifest fixes that: every pair file MUST have a curated STATUS here, or the build FAILS.
Run it after generating any pairs. It emits PAIRS_MANIFEST.md and exits non-zero on drift so the
registry can never silently diverge from disk.

STATUS vocabulary:
  canonical      - the live/correct version; eligible for a mixture (after sanction + dose)
  superseded     - an older version replaced by a canonical one; do NOT train (kept for provenance)
  QUARANTINED    - reviewed and REJECTED for training (e.g. teaches a defect); NEVER train
  raw-source     - raw/mined input used to DERIVE trainable rows; never trained directly
  derived        - the trainable output of a derive step (situation->right_way etc.)
  cpt-slice      - continued-pretraining text (schema {text,meta}), not an SFT pair
  eval-output    - probe/eval results, not training data
  needs-review   - present on disk, not yet classified — build FAILS until you classify it
"""
import glob, hashlib, json, os, subprocess, sys


def _data_root():
    """Training DATA lives in the private governed store (Jesse one-store ruling; Q1/Q2 gate
    2026-07-23). This tooling stays public; every .jsonl scan/read and the emitted
    PAIRS_MANIFEST.md resolve under TRAINING_DATA_ROOT. Fail-loud — a silent default would
    re-create data artifacts in the public tree."""
    root = os.environ.get("TRAINING_DATA_ROOT")
    if not root or not os.path.isdir(root):
        raise SystemExit(
            "TRAINING_DATA_ROOT is unset or not a directory. Point it at the governed store "
            "(<MIRA_HOME>/treasurer/foundations/careers/training_data/careers_qwen). "
            "See careers-qwen/TAEY_TRAINING_DOCTRINE.md."
        )
    # The STATUS allow-list already catches a wrong root, but it catches the CONSEQUENCE: point this
    # one level up at training_data/ and the recursive **/*.jsonl scan reaches 309 files instead of
    # 174, every one unlisted, so the build fails with 309 drift entries. Loud, but only after the
    # scan has walked directories it was never meant to see — which during the 2026-08-01 credential
    # quarantine included six files carrying plaintext host credentials that live OUTSIDE this root
    # and outside the manifest's protection. Assert the root IS the governed store, so a mis-set
    # value is refused before anything is walked rather than diagnosed from the wreckage after.
    if os.path.basename(os.path.normpath(root)) != "careers_qwen":
        raise SystemExit(
            f"TRAINING_DATA_ROOT must BE the governed store (a directory named 'careers_qwen'), "
            f"not a parent or sibling of it. Got: {root}. Pointing this at a parent makes the "
            f"recursive .jsonl scan reach files this manifest does not govern."
        )
    return root


