def git_tracked(relpath):
    # authoritative: git check-ignore -q returns 0 if the path IS ignored, 1 if NOT.
    # Runs against whichever repo owns the DATA ROOT (git resolves the repo from cwd) — after
    # the governed-store migration that is the treasurer repo, whose training_data/.gitignore
    # must keep every *.jsonl ignored.
    r = subprocess.run(["git", "check-ignore", "-q", os.path.join(ROOT, relpath)],
                       cwd=ROOT, capture_output=True)
    return r.returncode != 0   # not-ignored == tracked/trackable


def has_thinking(path):
    try:
        for line in open(path):
            if "<think>" in line:
                return True
            break
    except Exception:
        pass
    return False


def _assert_no_duplicate_status_keys():
    """FAIL if any path is classified twice in the STATUS literal above.

    STATUS is a dict literal, so a repeated key is not an error in Python — the LAST one silently
    wins and the earlier classification is discarded with no diagnostic. The drift check below can
    never see this: it asks whether a file is classified, and a doubly-classified file answers yes.

    Observed 2026-07-27: two seats registered corrections/linkedin_send_verification_v1.jsonl in the
    same minute — the author as "canonical" at one line, treasurer as "raw-source" a couple of lines
    later to clear the drift gate. The dict kept the raw-source entry, so the author's canonical
    classification vanished silently and the manifest published the wrong status. Concurrent seats
    editing one registry make this a recurring shape, not a one-off.

    Reads THIS FILE'S SOURCE rather than the built dict, because by the time STATUS exists as an
    object the duplicate has already collapsed and is unrecoverable.
    """
    import ast
    src = open(os.path.abspath(__file__), encoding="utf-8").read()
    dup = {}
    for node in ast.walk(ast.parse(src)):
        if not isinstance(node, ast.Dict) or len(node.keys) < 20:
            continue
        seen = {}
        for k in node.keys:
            if not isinstance(k, ast.Constant) or not isinstance(k.value, str):
                continue
            if k.value in seen:
                dup.setdefault(k.value, [seen[k.value]]).append(k.lineno)
            else:
                seen[k.value] = k.lineno
    if dup:
        print(f"\n❌ DUPLICATE STATUS KEYS — {len(dup)} path(s) classified more than once (build FAILS):")
        for path, lines in sorted(dup.items()):
            print(f"   - {path}")
            print(f"       lines {lines} — python keeps the LAST; every earlier classification is discarded")
        print("   Resolve to ONE entry per path. The file's AUTHOR owns its status.")
        sys.exit(1)


def _assert_no_rows_in_tooling_repo():
    """Rows written beside this script instead of under TRAINING_DATA_ROOT are INVISIBLE here —
    this builder only scans the governed store, so a stranded file is never classified, never
    appears in the manifest, and is never dosed. Discipline alone does not close that: four
    treasurer-sanctioned rows sat in data/staged/ for three days marked PENDING_TREASURER_MERGE
    while every gate reported clean. The wrong path must be DETECTABLE, so it is checked here —
    at the mandatory registration step every author already runs."""
    here = os.path.dirname(os.path.abspath(__file__))
    if os.path.abspath(here) == os.path.abspath(ROOT):
        return                                   # tooling and store colocated; nothing to separate
    stray = sorted(glob.glob(os.path.join(here, "**/*.jsonl"), recursive=True))
    if stray:
        print(f"\n❌ ROWS IN THE TOOLING REPO — {len(stray)} file(s) outside the governed store (build FAILS):")
        for p in stray:
            print(f"   - {os.path.relpath(p, here)}")
        print(f"   Move them under TRAINING_DATA_ROOT ({ROOT}) and register them in STATUS.")
        print("   A row here is unregistered, untrained, and invisible to every gate.")
        sys.exit(1)


def main():
    _assert_no_duplicate_status_keys()
    _assert_no_rows_in_tooling_repo()
    # BACKUP DIRECTORIES ARE NOT CORPUS. A pre-scrub copy exists to reverse an irreversible
    # in-place edit; it is deliberately a byte-for-byte snapshot of a PREVIOUS state, so requiring
    # it to be classified would mean maintaining a second, permanently-stale classification of
    # every file it shadows — and the moment those two disagree the manifest reports drift that is
    # not drift. Excluded by name pattern, and the exclusion is NARROW (it matches only the
    # prescrub naming) so an ordinary directory can never fall through it.
    # THESE STILL HOLD THE UNSCRUBBED CREDENTIAL MATERIAL. Deletion condition, stated so it is not
    # forgotten: remove both once a pack has run green against the scrubbed slices, proving the
    # scrub broke nothing. Until then they are the only reversal path.
    _BACKUP_MARKERS = (".prescrub_", "duplicates_prescrub_")
    _all = sorted(os.path.relpath(p, ROOT) for p in glob.glob(os.path.join(ROOT, "**/*.jsonl"), recursive=True))
    on_disk = [r for r in _all if not any(m in r for m in _BACKUP_MARKERS)]
    _skipped = len(_all) - len(on_disk)
    if _skipped:
        print(f"[manifest] {_skipped} file(s) in pre-scrub backup dirs excluded (not corpus; "
              f"delete once a pack runs green — see the note at this line)")
    drift = []
    rows_out = []
    for rel in on_disk:
        full = os.path.join(ROOT, rel)
        n = sum(1 for _ in open(full, errors="ignore"))
        h = hashlib.sha256(open(full, "rb").read()).hexdigest()[:12]
        try:
            schema = json.loads(open(full).readline()).get("schema", "-")
        except Exception:
            schema = "-"
        status, note = STATUS.get(rel, ("needs-review", "NOT CLASSIFIED — add to STATUS map"))
        if status == "needs-review":
            drift.append(rel)
        tracked = "git" if git_tracked(rel) else "IGNORED"
        thinking = "think" if has_thinking(full) else "-"
        rows_out.append((rel, n, status, tracked, schema, thinking, h, note))
    # manifest lists a file that no longer exists?
    for rel in STATUS:
        if rel not in on_disk:
            drift.append(f"{rel} (in STATUS map but MISSING on disk)")

    # emit
    with open(os.path.join(ROOT, "PAIRS_MANIFEST.md"), "w") as f:
        f.write("# PAIRS MANIFEST — the single source of truth for training-pair files\n\n")
        f.write("Generated by build_pairs_manifest.py (scans disk + curated STATUS). Re-run after any\n")
        f.write("pair generation; it FAILS on drift so this can never silently diverge from disk.\n\n")
        f.write("| file | rows | status | git | schema | thinking | sha | note |\n")
        f.write("|---|--:|---|---|---|---|---|---|\n")
        for rel, n, status, tracked, schema, thinking, h, note in rows_out:
            f.write(f"| `{rel}` | {n} | **{status}** | {tracked} | {schema} | {thinking} | {h} | {note} |\n")
        canon = [r for r in rows_out if r[2] == "canonical"]
        quar = [r for r in rows_out if r[2] == "QUARANTINED"]
        f.write(f"\n**canonical (trainable after sanction+dose): {len(canon)}** · "
                f"**QUARANTINED (never train): {len(quar)}** · total files: {len(rows_out)}\n")
        if quar:
            f.write("\n### ⛔ QUARANTINED — do NOT train:\n")
            for r in quar:
                f.write(f"- `{r[0]}` — {r[7]}\n")

    print(f"scanned {len(on_disk)} pair files -> PAIRS_MANIFEST.md")
    for rel, n, status, tracked, schema, thinking, h, note in rows_out:
        flag = " ⛔" if status == "QUARANTINED" else (" ⚠️IGNORED" if tracked == "IGNORED" and status not in ("eval-output",) else "")
        print(f"  {status:12} {n:>6}  {rel}{flag}")
    if drift:
        print(f"\n❌ DRIFT — {len(drift)} unclassified/missing (build FAILS):")
        for d in drift:
            print(f"   - {d}")
        return 1
    print("\n✓ no drift — every pair file is classified")
    return 0


if __name__ == "__main__":
    sys.exit(main())
